import{_ as i,a0 as p,w as r,s as g,ao as o,I as t,x as a,a1 as n,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在 Linux 系統中手動滾動日誌 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 系統中手動滾動日誌 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 系統中手動滾動日誌 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 系統中手動滾動日誌 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200319 Manually rotating log files on Linux","title":"在 Linux 系統中手動滾動日誌","tag":"202003","desc":""},"relativePath":"202003/20200319 Manually rotating log files on Linux.md","filePath":"[post].md"}'),d={name:"202003/20200319 Manually rotating log files on Linux.md"};function c(h,s,u,k,y,b){const l=p("Link");return r(),g("div",null,[s[20]||(s[20]=o('<h1 id="在-linux-系統中手動滾動日誌" tabindex="-1">在 Linux 系統中手動滾動日誌 <a class="header-anchor" href="#在-linux-系統中手動滾動日誌" aria-label="Permalink to “在 Linux 系統中手動滾動日誌”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202003/25/223932xqibwq5fafx5ao3f.jpg" alt=""></p><p><ruby>日誌滾動<rt>log rotation</rt></ruby>在 Linux 系統上是再常見不過的一個功能了，它為系統監控和故障排查保留必要的日誌內容，同時又防止過多的日誌造成單個日誌文件太大。</p><p>日誌滾動的過程是這樣的：在一組日誌文件之中，編號最大的（最舊的）一個日誌文件會被刪除，其餘的日誌文件編號則依次增大並取代較舊的日誌文件，而較新的文件則取代它作為當前的日誌文件。這一個過程很容易就可以實現自動化，在細節上還能按需作出微調。</p><p>使用 <code>logrotate</code> 命令可以手動執行日誌滾動的操作。本文將要介紹的就是手動進行日誌滾動的方法，以及預期產生的結果。</p><p>文中出現的示例適用於 Ubuntu 等 Linux 系統，對於其它類型的系統，日誌文件和配置文件可能會有所不同，但日誌滾動的過程是大同小異的。</p><h3 id="為什麼需要滾動日誌" tabindex="-1">為什麼需要滾動日誌 <a class="header-anchor" href="#為什麼需要滾動日誌" aria-label="Permalink to “為什麼需要滾動日誌”">​</a></h3><p>一般情況下，無需手動旋轉日誌文件。Linux 系統會每隔一天（或間隔更長的時間）或根據日誌文件的大小自動進行一次日誌滾動。如果你需要滾動日誌以釋放存儲空間，又或者將某一部分日誌從當前的活動中分割出來，這很容易做到，具體要取決於文件滾動規則。</p><h3 id="一點背景介紹" tabindex="-1">一點背景介紹 <a class="header-anchor" href="#一點背景介紹" aria-label="Permalink to “一點背景介紹”">​</a></h3>',9)),t("p",null,[s[1]||(s[1]=a("在 Linux 系統安裝完成後就已經有很多日誌文件被納入到日誌滾動的範圍內了。另外，一些應用程序在安裝時也會為自己產生的日誌文件設置滾動規則。一般來説，日誌滾動的配置文件會放置在 ",-1)),s[2]||(s[2]=t("code",null,"/etc/logrotate.d",-1)),s[3]||(s[3]=a("。如果你想了解日誌滾動的詳細實現，可以參考",-1)),n(l,{href:"https://www.networkworld.com/article/3218728/how-log-rotation-works-with-logrotate.html"},{default:e(()=>[...s[0]||(s[0]=[a("這篇以前的文章",-1)])]),_:1}),s[4]||(s[4]=a("。",-1))]),s[21]||(s[21]=o(`<p>在日誌滾動的過程中，活動日誌會以一個新名稱命名，例如 <code>log.1</code>，之前被命名為 <code>log.1</code> 的文件則會被重命名為 <code>log.2</code>，依此類推。在這一組文件中，最舊的日誌文件（假如名為 <code>log.7</code>）會從系統中刪除。日誌滾動時文件的命名方式、保留日誌文件的數量等參數是由 <code>/etc/logrotate.d</code> 目錄中的配置文件決定的，因此你可能會看到有些日誌文件只保留少數幾次滾動，而有些日誌文件的滾動次數會到 7 次或更多。</p><p>例如 <code>syslog</code> 在經過日誌滾動之後可能會如下所示（注意，行尾的註釋部分只是説明滾動過程是如何對文件名產生影響的）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /var/log/syslog*</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  128674 Mar 10 08:00 /var/log/syslog      &lt;== 新文件</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm 2405968 Mar  9 16:09 /var/log/syslog.1    &lt;== 之前的 syslog</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  206451 Mar  9 00:00 /var/log/syslog.2.gz &lt;== 之前的 syslog.1</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  216852 Mar  8 00:00 /var/log/syslog.3.gz &lt;== 之前的 syslog.2.gz</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  212889 Mar  7 00:00 /var/log/syslog.4.gz &lt;== 之前的 syslog.3.gz</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  219106 Mar  6 00:00 /var/log/syslog.5.gz &lt;== 之前的 syslog.4.gz</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  218596 Mar  5 00:00 /var/log/syslog.6.gz &lt;== 之前的 syslog.5.gz</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  211074 Mar  4 00:00 /var/log/syslog.7.gz &lt;== 之前的 syslog.6.gz</span></span></code></pre></div><p>你可能會發現，除了當前活動的日誌和最新一次滾動的日誌文件之外，其餘的文件都已經被壓縮以節省存儲空間。這樣設計的原因是大部分系統管理員都只需要查閲最新的日誌文件，其餘的日誌文件壓縮起來，需要的時候可以解壓查閲，這是一個很好的折中方案。</p><h3 id="手動日誌滾動" tabindex="-1">手動日誌滾動 <a class="header-anchor" href="#手動日誌滾動" aria-label="Permalink to “手動日誌滾動”">​</a></h3><p>你可以這樣執行 <code>logrotate</code> 命令進行手動日誌滾動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo logrotate -f /etc/logrotate.d/rsyslog</span></span></code></pre></div><p>值得一提的是，<code>logrotate</code> 命令使用 <code>/etc/logrotate.d/rsyslog</code> 這個配置文件，並通過了 <code>-f</code> 參數實行“強制滾動”。因此，整個過程將會是：</p><ul><li>刪除 <code>syslog.7.gz</code>，</li><li>將原來的 <code>syslog.6.gz</code> 命名為 <code>syslog.7.gz</code>，</li><li>將原來的 <code>syslog.5.gz</code> 命名為 <code>syslog.6.gz</code>，</li><li>將原來的 <code>syslog.4.gz</code> 命名為 <code>syslog.5.gz</code>，</li><li>將原來的 <code>syslog.3.gz</code> 命名為 <code>syslog.4.gz</code>，</li><li>將原來的 <code>syslog.2.gz</code> 命名為 <code>syslog.3.gz</code>，</li><li>將原來的 <code>syslog.1.gz</code> 命名為 <code>syslog.2.gz</code>，</li><li>但新的 <code>syslog</code> 文件不一定必須創建。</li></ul><p>你可以按照下面的幾條命令執行操作，以確保文件的屬主和權限正確：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo touch /var/log/syslog</span></span>
<span class="line"><span>$ sudo chown syslog:adm /var/log/syslog</span></span>
<span class="line"><span>$ sudo chmod 640 /var/log/syslog</span></span></code></pre></div><p>你也可以把以下這一行內容添加到 <code>/etc/logrotate.d/rsyslog</code> 當中，由 <code>logrotate</code> 來幫你完成上面三條命令的操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>create 0640 syslog adm</span></span></code></pre></div><p>整個配置文件的內容是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/var/log/syslog</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>rotate 7</span></span>
<span class="line"><span>daily</span></span>
<span class="line"><span>missingok</span></span>
<span class="line"><span>notifempty</span></span>
<span class="line"><span>create 0640 syslog adm           &lt;==</span></span>
<span class="line"><span>delaycompress</span></span>
<span class="line"><span>compress</span></span>
<span class="line"><span>postrotate</span></span>
<span class="line"><span>/usr/lib/rsyslog/rsyslog-rotate</span></span>
<span class="line"><span>endscript</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>下面是手動滾動記錄用户登錄信息的 <code>wtmp</code> 日誌的示例。由於 <code>/etc/logrotate.d/wtmp</code> 中有 <code>rotate 2</code> 的配置，因此係統中只保留了兩份 <code>wtmp</code> 日誌文件。</p><p>滾動前：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l wtmp*</span></span>
<span class="line"><span>-rw-r----- 1 root utmp  1152 Mar 12 11:49 wtmp</span></span>
<span class="line"><span>-rw-r----- 1 root utmp   768 Mar 11 17:04 wtmp.1</span></span></code></pre></div><p>執行滾動命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo logrotate -f /etc/logrotate.d/wtmp</span></span></code></pre></div><p>滾動後：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /var/log/wtmp*</span></span>
<span class="line"><span>-rw-r----- 1 root utmp     0 Mar 12 11:52 /var/log/wtmp</span></span>
<span class="line"><span>-rw-r----- 1 root utmp  1152 Mar 12 11:49 /var/log/wtmp.1</span></span>
<span class="line"><span>-rw-r----- 1 root adm  99726 Feb 21 07:46 /var/log/wtmp.report</span></span></code></pre></div><p>需要知道的是，無論發生的日誌滾動是自動滾動還是手動滾動，最近一次的滾動時間都會記錄在 <code>logrorate</code> 的狀態文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep wtmp /var/lib/logrotate/status</span></span>
<span class="line"><span>&quot;/var/log/wtmp&quot; 2020-3-12-11:52:57</span></span></code></pre></div><hr>`,25)),t("p",null,[s[6]||(s[6]=a("via: ",-1)),n(l,{href:"https://www.networkworld.com/article/3531969/manually-rotating-log-files-on-linux.html"},{default:e(()=>[...s[5]||(s[5]=[a("https://www.networkworld.com/article/3531969/manually-rotating-log-files-on-linux.html",-1)])]),_:1})]),t("p",null,[s[11]||(s[11]=a("作者：",-1)),n(l,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:e(()=>[...s[7]||(s[7]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[12]||(s[12]=a(" 選題：",-1)),n(l,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 譯者：",-1)),n(l,{href:"https://github.com/HankChow"},{default:e(()=>[...s[9]||(s[9]=[a("HankChow",-1)])]),_:1}),s[14]||(s[14]=a(" 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:e(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[17]||(s[17]=a("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原創編譯，",-1)),n(l,{href:"https://linux.cn/"},{default:e(()=>[...s[16]||(s[16]=[a("Linux中國",-1)])]),_:1}),s[19]||(s[19]=a(" 榮譽推出",-1))])])}const x=i(d,[["render",c]]);export{w as __pageData,x as default};
